// === 1. 组件局部状态：useState ===
function ToggleButton() {
  const [active, setActive] = useState(false);
  return (
    <button onClick={() => setActive(prev => !prev)}>
      {active ? 'ON' : 'OFF'}
    </button>
  );
}

// === 2. 跨组件共享状态：Zustand ===
import { create } from 'zustand';

const useAuthStore = create((set) => ({
  user: null,
  token: '',
  isAuthenticated: false,
  login: async (credentials) => {
    const { user, token } = await api.login(credentials);
    set({ user, token, isAuthenticated: true });
  },
  logout: () => set({ user: null, token: '', isAuthenticated: false }),
}));

// 组件中按需订阅，避免无关状态变化触发重渲染
function UserProfile() {
  const userName = useAuthStore(state => state.user?.name ?? 'Guest');
  return <span>{userName}</span>;
}

// === 3. 服务端缓存：React Query ===
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';

function UserList() {
  const { data, isLoading, error } = useQuery({
    queryKey: ['users'],
    queryFn: () => fetch('/api/users').then(r => r.json()),
    staleTime: 5 * 60 * 1000,
  });
  if (isLoading) return <Spinner />;
  if (error) return <ErrorMessage error={error} />;
  return <ul>{data.map(u => <li key={u.id}>{u.name}</li>)}</ul>;
}

// 乐观更新示例
function AddUser() {
  const queryClient = useQueryClient();
  const mutation = useMutation({
    mutationFn: (newUser) => api.post('/api/users', newUser),
    onMutate: async (newUser) => {
      await queryClient.cancelQueries({ queryKey: ['users'] });
      const previous = queryClient.getQueryData(['users']);
      queryClient.setQueryData(['users'], old => [...old, newUser]);
      return { previous };
    },
    onError: (err, newUser, context) => {
      queryClient.setQueryData(['users'], context.previous);
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ['users'] });
    },
  });
}

// === 4. 派生状态：selector 实时算，不单独存 ===
import { createSelector } from '@reduxjs/toolkit';

const selectTodos = state => state.todos;
const selectFilter = state => state.filter;

const selectFilteredTodos = createSelector(
  [selectTodos, selectFilter],
  (todos, filter) => {
    switch (filter) {
      case 'active': return todos.filter(t => !t.done);
      case 'completed': return todos.filter(t => t.done);
      default: return todos;
    }
  }
);

// === 5. 状态机：XState v5 ===
import { createMachine, assign, fromPromise } from 'xstate';

const fetchMachine = createMachine({
  id: 'fetch',
  initial: 'idle',
  context: { data: null, error: null, retries: 0 },
  states: {
    idle: {
      on: { FETCH: { target: 'loading', actions: assign({ retries: 0 }) } }
    },
    loading: {
      invoke: {
        src: fromPromise(async ({ input }) => {
          const res = await fetch(input.url);
          if (!res.ok) throw new Error('Fetch failed');
          return res.json();
        }),
        input: ({ context }) => ({ url: context.url }),
        onDone: {
          target: 'success',
          actions: assign({ data: ({ event }) => event.output })
        },
        onError: {
          target: 'error',
          actions: assign({ error: ({ event }) => event.error })
        }
      }
    },
    success: {
      on: { RETRY: 'loading', RESET: 'idle' }
    },
    error: {
      on: {
        RETRY: {
          target: 'loading',
          guard: ({ context }) => context.retries < 3,
          actions: assign({ retries: ({ context }) => context.retries + 1 })
        },
        RESET: 'idle'
      }
    }
  }
});

// === 6. 状态持久化：Zustand persist ===
import { persist } from 'zustand/middleware';

const useSettingsStore = create(
  persist(
    (set) => ({
      theme: 'light',
      language: 'zh',
      setTheme: (theme) => set({ theme }),
      setLanguage: (language) => set({ language }),
    }),
    {
      name: 'app-settings',
      version: 1,
      migrate: (persisted, version) => {
        if (version === 0) {
          return { ...persisted, language: 'zh' };
        }
        return persisted;
      },
    }
  )
);
